1	// pytypes.mjs — shared Python value wrappers and semantics helpers.
2	// Pure Node ESM: no imports, no JSON, no RegExp.
3	
4	// ---------- helpers ----------
5	
6	export function isNegativeZero(value) {
7	  return Object.is(value, -0);
8	}
9	
10	// Booleans, BigInts, and finite integral numbers count as "int-like" in Python terms.
11	export function pythonIntLike(value) {
12	  if (typeof value === 'boolean' || typeof value === 'bigint') return true;
13	  return typeof value === 'number' && Number.isFinite(value) && Math.floor(value) === value;
14	}
15	
16	function typeName(value) {
17	  if (value === null || value === undefined) return 'NoneType';
18	  if (typeof value === 'boolean') return 'bool';
19	  if (typeof value === 'bigint') return 'int';
20	  if (typeof value === 'number') return Number.isInteger(value) ? 'int' : 'float';
21	  if (typeof value === 'string') return 'str';
22	  if (Array.isArray(value)) return 'list';
23	  if (value instanceof PyTuple) return 'tuple';
24	  if (value instanceof PyFrozenSet) return 'frozenset';
25	  if (value instanceof PySet) return 'set';
26	  if (value instanceof PyBytes) return 'bytes';
27	  if (value instanceof PyComplex) return 'complex';
28	  if (value instanceof PyRange) return 'range';
29	  if (value instanceof PyDict) return 'dict';
30	  return typeof value;
31	}
32	
33	// ---------- wrapper classes ----------
34	
35	export class PyTuple {
36	  constructor(items) {
37	    this.items = items;
38	  }
39	}
40	
41	export class PyFrozenSet {
42	  constructor(items) {
43	    // Frozensets dedupe members by Python equality.
44	    const deduped = [];
45	    for (const item of items) {
46	      if (!deduped.some((existing) => pythonEquals(existing, item))) deduped.push(item);
47	    }
48	    this.items = deduped;
49	  }
50	}
51	
52	export class PySet {
53	  constructor(items = []) {
54	    this.entries = [];
55	    for (const item of items) this.add(item);
56	  }
57	
58	  // Adds item unless an equal member already exists; insertion order kept.
59	  add(item) {
60	    if (!this.entries.some((existing) => pythonEquals(existing, item))) {
61	      this.entries.push(item);
62	    }
63	  }
64	
65	  getEntries() {
66	    return this.entries;
67	  }
68	}
69	
70	export class PyBytes {
71	  constructor(bytes) {
72	    this.bytes = bytes; // Uint8Array
73	  }
74	}
75	
76	export class PyComplex {
77	  constructor(real, imag) {
78	    this.real = real;
79	    this.imag = imag;
80	  }
81	}
82	
83	export class PyRange {
84	  constructor(start, stop, step) {
85	    this.start = start;
86	    this.stop = stop;
87	    this.step = step === undefined ? 1 : step;
88	  }
89	}
