91	export class PyDict {
92	  // entries: iterable of [key, value] pairs, insertion order preserved.
93	  constructor(entries = []) {
94	    this.entries = [];
95	    for (const pair of entries) this.set(pair[0], pair[1]);
96	  }
97	
98	  // Python dict semantics: an equal key keeps its original position and key,
99	  // only the value is replaced (True/1/1.0 collapse; NaN never collapses).
100	  set(key, value) {
101	    for (const pair of this.entries) {
102	      if (pythonEquals(pair[0], key)) {
103	        pair[1] = value;
104	        return;
105	      }
106	    }
107	    this.entries.push([key, value]);
108	  }
109	
110	  getEntries() {
111	    return this.entries;
112	  }
113	}
114	
115	// ---------- equality ----------
116	
117	// Normalize bools to numbers; BigInts pass through untouched.
118	function asNumeric(value) {
119	  return typeof value === 'boolean' ? Number(value) : value;
120	}
121	
122	// Exact equality across bool/int(BigInt)/float. An integral double converts to
123	// BigInt exactly, so 9007199254740993n != 9007199254740992 (the double); a
124	// nonintegral double can never equal an integer.
125	function numericEquals(a, b) {
126	  const x = asNumeric(a);
127	  const y = asNumeric(b);
128	  const xBig = typeof x === 'bigint';
129	  const yBig = typeof y === 'bigint';
130	  if (xBig && yBig) return x === y;
131	  if (xBig || yBig) {
132	    const big = xBig ? x : y;
133	    const num = xBig ? y : x;
134	    if (!Number.isFinite(num) || !Number.isInteger(num)) return false;
135	    return big === BigInt(num);
136	  }
137	  return x === y;
138	}
139	
140	// Ordering across bool/int(BigInt)/float, exact for integral values. For a
141	// nonintegral double n and integer i: i < n iff i <= floor(n), n < i iff
142	// ceil(n) <= i — this avoids precision loss from Number(bigint) rounding.
143	function numericLessThan(a, b) {
144	  const x = asNumeric(a);
145	  const y = asNumeric(b);
146	  const xBig = typeof x === 'bigint';
147	  const yBig = typeof y === 'bigint';
148	  if (xBig && yBig) return x < y;
149	  if (!xBig && !yBig) {
150	    if (Number.isNaN(x) || Number.isNaN(y)) return false; // Python: NaN < x is False
151	    return x < y;
152	  }
153	  if (xBig) {
154	    if (Number.isNaN(y)) return false;
155	    if (y === Infinity) return true;
156	    if (y === -Infinity) return false;
157	    if (Number.isInteger(y)) return x < BigInt(y);
158	    return x <= BigInt(Math.floor(y));
159	  }
160	  if (Number.isNaN(x)) return false;
161	  if (x === Infinity) return false;
162	  if (x === -Infinity) return true;
163	  if (Number.isInteger(x)) return BigInt(x) < y;
164	  return BigInt(Math.ceil(x)) <= y;
165	}
