167	export function pythonEquals(a, b) {
168	  // Fast path covers identical primitives/objects. NaN !== NaN in Python;
169	  // -0 == 0 in Python even though Object.is tells them apart.
170	  if (a === b) return !(typeof a === 'number' && Number.isNaN(a));
171	  // -0 == 0 in Python even though Object.is tells them apart.
172	  if (isNegativeZero(a) && b === 0) return true;
173	  if (isNegativeZero(b) && a === 0) return true;
174	
175	  // None-like values only equal each other (handled above).
176	  if (a === null || a === undefined || b === null || b === undefined) return false;
177	
178	  // bool/int(BigInt)/float cross-comparison: True == 1 == 1n == 1.0.
179	  const aNum = typeof a === 'boolean' || typeof a === 'number' || typeof a === 'bigint';
180	  const bNum = typeof b === 'boolean' || typeof b === 'number' || typeof b === 'bigint';
181	  if (aNum && bNum) return numericEquals(a, b);
182	  if (typeof a === 'string' || typeof b === 'string') return false;
183	
184	  // Complex: 1+0j == 1 holds in Python.
185	  if (a instanceof PyComplex || b instanceof PyComplex) {
186	    if (!(aNum || a instanceof PyComplex) || !(bNum || b instanceof PyComplex)) return false;
187	    const ca = a instanceof PyComplex ? a : new PyComplex(Number(a), 0);
188	    const cb = b instanceof PyComplex ? b : new PyComplex(Number(b), 0);
189	    return ca.real === cb.real && ca.imag === cb.imag;
190	  }
191	
192	  if (Array.isArray(a) && Array.isArray(b)) {
193	    return a.length === b.length && a.every((item, i) => pythonEquals(item, b[i]));
194	  }
195	  if (a instanceof PyTuple && b instanceof PyTuple) {
196	    return a.items.length === b.items.length &&
197	      a.items.every((item, i) => pythonEquals(item, b.items[i]));
198	  }
199	  if (a instanceof PyBytes && b instanceof PyBytes) {
200	    const x = a.bytes;
201	    const y = b.bytes;
202	    if (x.length !== y.length) return false;
203	    for (let i = 0; i < x.length; i++) if (x[i] !== y[i]) return false;
204	    return true;
205	  }
206	  // Sets compare as Python sets: set == frozenset when members match.
207	  const aSet = a instanceof PyFrozenSet || a instanceof PySet;
208	  const bSet = b instanceof PyFrozenSet || b instanceof PySet;
209	  if (aSet && bSet) {
210	    const aItems = a instanceof PyFrozenSet ? a.items : a.entries;
211	    const bItems = b instanceof PyFrozenSet ? b.items : b.entries;
212	    return aItems.length === bItems.length &&
213	      aItems.every((item) => bItems.some((other) => pythonEquals(item, other)));
214	  }
215	  if (aSet !== bSet) return false;
216	  if (a instanceof PyDict && b instanceof PyDict) {
217	    if (a.entries.length !== b.entries.length) return false;
218	    return a.entries.every(([key, value]) => {
219	      for (const [bKey, bValue] of b.entries) {
220	        if (pythonEquals(key, bKey)) return pythonEquals(value, bValue);
221	      }
222	      return false;
223	    });
224	  }
225	  return false;
226	}
