228	// ---------- ordering ----------
229	
230	// Compare two strings by Unicode code points (as Python does), not UTF-16 units.
231	function compareCodePoints(a, b) {
232	  let i = 0;
233	  let j = 0;
234	  while (i < a.length && j < b.length) {
235	    const ca = a.codePointAt(i);
236	    const cb = b.codePointAt(j);
237	    if (ca !== cb) return ca < cb ? -1 : 1;
238	    i += ca > 0xffff ? 2 : 1;
239	    j += cb > 0xffff ? 2 : 1;
240	  }
241	  if (i < a.length) return 1;
242	  if (j < b.length) return -1;
243	  return 0;
244	}
245	
246	function sequenceLessThan(aItems, bItems) {
247	  const n = Math.min(aItems.length, bItems.length);
248	  for (let i = 0; i < n; i++) {
249	    if (!pythonEquals(aItems[i], bItems[i])) return pythonLessThan(aItems[i], bItems[i]);
250	  }
251	  return aItems.length < bItems.length;
252	}
253	
254	export function pythonLessThan(a, b) {
255	  const aNum = typeof a === 'boolean' || typeof a === 'number' || typeof a === 'bigint';
256	  const bNum = typeof b === 'boolean' || typeof b === 'number' || typeof b === 'bigint';
257	  if (aNum && bNum) return numericLessThan(a, b);
258	  if (typeof a === 'string' && typeof b === 'string') return compareCodePoints(a, b) < 0;
259	  if (Array.isArray(a) && Array.isArray(b)) return sequenceLessThan(a, b);
260	  if (a instanceof PyTuple && b instanceof PyTuple) return sequenceLessThan(a.items, b.items);
261	  throw new TypeError(
262	    "'<' not supported between instances of '" + typeName(a) + "' and '" + typeName(b) + "'"
263	  );
264	}
