266	// ---------- float repr ----------
267	
268	// Split a finite, positive double into shortest-round-trip digits and decpt,
269	// where value === 0.d1d2... * 10^decpt (digits carry no trailing zeros).
270	function shortestDigits(value) {
271	  const s = String(value); // JS also yields the shortest round-trip decimal
272	  const ePos = s.indexOf('e');
273	  let mantissa;
274	  let exp;
275	  if (ePos >= 0) {
276	    mantissa = s.slice(0, ePos);
277	    exp = Number(s.slice(ePos + 1));
278	  } else {
279	    mantissa = s;
280	    exp = 0;
281	  }
282	  const dotPos = mantissa.indexOf('.');
283	  let intPart;
284	  let fracPart;
285	  if (dotPos >= 0) {
286	    intPart = mantissa.slice(0, dotPos);
287	    fracPart = mantissa.slice(dotPos + 1);
288	  } else {
289	    intPart = mantissa;
290	    fracPart = '';
291	  }
292	  let digits;
293	  let decpt;
294	  if (intPart === '0' || intPart === '') {
295	    // value < 1: skip leading zeros of the fraction
296	    let zeros = 0;
297	    while (zeros < fracPart.length && fracPart.charAt(zeros) === '0') zeros++;
298	    digits = fracPart.slice(zeros);
299	    decpt = exp - zeros;
300	  } else {
301	    digits = intPart + fracPart;
302	    decpt = exp + intPart.length;
303	  }
304	  // Strip trailing zeros; decpt is unaffected (0.1500 -> 0.15).
305	  let end = digits.length;
306	  while (end > 1 && digits.charAt(end - 1) === '0') end--;
307	  return { digits: digits.slice(0, end), decpt };
308	}
309	
310	// Emulate CPython repr(float): fixed notation for -3 <= decpt <= 16,
311	// scientific notation outside that range, exponent at least two digits.
312	export function pythonFloatRepr(value) {
313	  if (Number.isNaN(value)) return 'nan';
314	  if (value === Infinity) return 'inf';
315	  if (value === -Infinity) return '-inf';
316	  if (value === 0) return isNegativeZero(value) ? '-0.0' : '0.0';
317	
318	  const sign = value < 0 ? '-' : '';
319	  const { digits, decpt } = shortestDigits(Math.abs(value));
320	
321	  if (decpt > 16 || decpt <= -4) {
322	    const e = decpt - 1;
323	    const absE = Math.abs(e);
324	    const expStr = (e < 0 ? '-' : '+') + (absE < 10 ? '0' + String(absE) : String(absE));
325	    const mantissa = digits.length > 1
326	      ? digits.charAt(0) + '.' + digits.slice(1)
327	      : digits.charAt(0);
328	    return sign + mantissa + 'e' + expStr;
329	  }
330	  if (decpt <= 0) {
331	    return sign + '0.' + '0'.repeat(-decpt) + digits;
332	  }
333	  if (decpt >= digits.length) {
334	    return sign + digits + '0'.repeat(decpt - digits.length) + '.0';
335	  }
336	  return sign + digits.slice(0, decpt) + '.' + digits.slice(decpt);
337	}
